    (!isfinite(previous_time)) || (!isfinite(current_time)) || 
    (!isfinite(gain)) || (!isfinite(limit))) {
    return ADCS_E_RANGE;
}

if (gain < 0.0 || limit < 0.0) {
    return ADCS_E_RANGE;
}

if (current_time <= previous_time) {
    return ADCS_E_RANGE;
}

*rate = (adcs_vec3_t){0.0, 0.0, 0.0};
command->command = (adcs_vec3_t){0.0, 0.0, 0.0};
command->saturated_axes = 0U;
*torque = (adcs_vec3_t){0.0, 0.0, 0.0};

