temp_state.previous_field_t = *previous;
temp_state.previous_time_s = previous_time;
temp_state.initialized = 1;

adcs_status_t status = adcs_bdot_update(&temp_state, current, current_time, 1.0, rate);
if (status != ADCS_OK) {
    return status;
}

status = adcs_bdot_dipole(current, rate, gain, limit, command);
